# for meca samples only
library(readxl)
library(ggplot2)
library(dplyr)

#  READ DATA
# ADMIXTURE ancestry proportions
adm <- read_excel("merged_10.3.xlsx")

# RNAScope-Ancestry ancestry proportions
meca <- read.table(
  "visit_1-20.3.Q",
  header = TRUE
)

# Population/sample labels
labels <- read.table(
  "update_ids_m.txt",
  header = FALSE
)

# Add population IDs to RNAScope-Ancestry results
meca$Population <- labels$V3


# MERGE ADMIXTURE AND RNASCOPE-ANCESTRY RESULTS
dat <- merge(
  adm,
  meca,
  by = "Population",
  suffixes = c("_ADM", "_MECA")
)

# Check merged data
head(dat)

# Number of samples in merged dataset
nrow(dat)


# IDENTIFY MECA QUERY SAMPLES
# MECA query samples are AFR1–AFR490
dat_query <- dat[
  grepl("^AFR[0-9]+$", dat$Population),
]

# Check number of MECA samples
length(unique(dat_query$Population))

# Check IDs
head(dat_query$Population)
tail(dat_query$Population)


# FUNCTION TO CALCULATE METRICS
calculate_metrics <- function(data, ancestry) {
  
  adm_col  <- paste0(ancestry, "_ADM")
  meca_col <- paste0(ancestry, "_MECA")
  
  # Pearson correlation
  cor_test <- cor.test(
    data[[adm_col]],
    data[[meca_col]],
    method = "pearson"
  )
  
  # Pearson r
  r <- unname(cor_test$estimate)
  
  # R-squared
  r2 <- r^2
  
  # P-value
  p_value <- cor_test$p.value
  
  # Mean Absolute Difference
  mad <- mean(
    abs(data[[adm_col]] - data[[meca_col]]),
    na.rm = TRUE
  )
  
  data.frame(
    Ancestry = ancestry,
    N = nrow(data),
    Pearson_r = r,
    R2 = r2,
    P_value = p_value,
    MAD = mad
  )
}


# METRICS — ALL SAMPLES
metrics_all <- bind_rows(
  calculate_metrics(dat, "African"),
  calculate_metrics(dat, "European"),
  calculate_metrics(dat, "American")
)

metrics_all


# METRICS — MECA QUERY SAMPLES ONLY
metrics_query <- bind_rows(
  calculate_metrics(dat_query, "African"),
  calculate_metrics(dat_query, "European"),
  calculate_metrics(dat_query, "American")
)

metrics_query


# COMBINE METRICS
metrics_all$Dataset <- "All samples"
metrics_query$Dataset <- "MECA query only"

metrics_combined <- bind_rows(
