# OPTIONAL: ADD R AND R² TO THE QUERY PLOTS
# Function to extract r and R2
get_annotation <- function(data, ancestry) {
  
  adm_col  <- paste0(ancestry, "_ADM")
  meca_col <- paste0(ancestry, "_MECA")
  
  r <- cor(
    data[[adm_col]],
    data[[meca_col]],
    use = "complete.obs",
    method = "pearson"
  )
  
  r2 <- r^2
  
  paste0(
    "r = ", round(r, 3),
    "\nR² = ", round(r2, 3)
  )
}


Afr_label <- get_annotation(dat_query, "African")
Eur_label <- get_annotation(dat_query, "European")
Amr_label <- get_annotation(dat_query, "American")


# African
Afr_query +
  annotate(
