# LINEAR REGRESSION SUMMARY — MECA QUERY ONLY
get_regression_summary <- function(data, ancestry) {
  
  adm_col  <- paste0(ancestry, "_ADM")
  meca_col <- paste0(ancestry, "_MECA")
  
  # Linear regression:
  # RNAScope-Ancestry = intercept + slope * ADMIXTURE
  model <- lm(
    data[[meca_col]] ~ data[[adm_col]],
    data = data
  )
  
  model_summary <- summary(model)
  
  # Extract coefficients
  intercept <- coef(model)[1]
  slope <- coef(model)[2]
  
  # R-squared
  r2 <- model_summary$r.squared
  
  # P-value for slope
  p_value <- coef(model_summary)[2, 4]
  
  # Pearson correlation
  r <- cor(
    data[[adm_col]],
    data[[meca_col]],
    use = "complete.obs",
    method = "pearson"
  )
  
  # Mean Absolute Difference
  mad <- mean(
    abs(data[[adm_col]] - data[[meca_col]]),
    na.rm = TRUE
  )
  
  data.frame(
    Dataset = "MECA query only",
    Ancestry = ancestry,
    N = nrow(data),
    Pearson_r = r,
    R2 = r2,
    P_value = p_value,
    MAD = mad,
    Intercept = intercept,
    Slope = slope,
    Equation = paste0(
      "Y = ",
      round(intercept, 5),
      " + ",
      round(slope, 5),
      "X"
    )
  )
}


# Calculate regression summaries
regression_query <- bind_rows(
  get_regression_summary(dat_query, "African"),
  get_regression_summary(dat_query, "European"),
  get_regression_summary(dat_query, "American")
)

regression_query